function l(e){return e.kind==="cmds"?{commands:e.commands,verification:e.verification,debt:e.debt}:"items"in e?{exercices:e.items,piege:e.piege}:{exercices:[{titre:e.titre,etapes:e.etapes,output:e.output,critere:e.critere}],piege:e.piege}}function y({why:e,system:i,choice:t,senior:r,errors:o,invariants:a,practice:u,verification:c}){return{why:`<p>${e}</p>`,system:`<p>${i}</p>`,choice:{kind:"free",html:`<p>${t}</p>`},senior:`<p>${r}</p>`,errors:o,invariants:a,practice:l(u),verification:c}}function P(e){return{js:e,python:e}}function v(e,i,t){return{...t,part:e,status:"Modèle stabilisé",category:i,level:"Tout niveau",tabs:[{id:"universel",label:"Universel"}]}}function n({id:e,label:i,icon:t,kind:r,niveau:o,why:a,system:u,choice:c,senior:p,errors:d,invariants:m,practice:g,verification:q}){return{id:e,label:i,icon:t,kind:r,os:"all",osLabel:"Universel",niveau:o,sections:{why:`<p>${a}</p>`,system:f(u),choice:{kind:"free",html:`<p>${c}</p>`},senior:`<p>${p}</p>`,errors:d,invariants:m,practice:l(g),verification:q}}}function f(e){return(e.match(/ref-fiche/g)??[]).length>=2?`<p>${e}</p>`:`<p>${e}</p><p>Dans la progression Collaboration, cette pratique relie les dynamiques internes d'équipe <span class="ref-fiche">→ Co01</span>, la communication hors équipe <span class="ref-fiche">→ Co02</span>, la mémoire documentaire <span class="ref-fiche">→ Co03</span> et l'organisation du travail <span class="ref-fiche">→ Co04</span>. Elle prolonge aussi les workflows techniques <span class="ref-fiche">→ T05</span> et les arbitrages de conception <span class="ref-fiche">→ C05</span> quand le travail devient collectif.</p>`}function s(e){return v("Co","Collaboration",e)}const b=s({id:"collaboration-equipe-technique",number:1,title:"Travailler en Équipe Technique",subtitle:"Construire la confiance, reviewer mieux, résoudre les désaccords et accueillir les nouveaux.",badge:"Fiche Co01 — Vision Systémique",meta:["5 nœuds · universel","8 sections / nœud"],readingTime:"35 min",description:"Les pratiques humaines et techniques qui rendent une équipe de développement vraiment efficace.",accent:"humain",nodes:{confianceEquipe:n({id:"confianceEquipe",label:"Confiance dans l'équipe",icon:"🤝",kind:"humain",niveau:"Fondation",why:"La vitesse d'une équipe n'est pas limitée par son meilleur développeur, mais par la friction entre ses membres. La confiance réduit cette friction et permet d'apprendre sans se protéger en permanence.",system:"Sans confiance, le code review devient politique, le feedback devient blessant, les conflits deviennent personnels et l'onboarding démarre dans le doute.",choice:"La confiance se construit par vulnérabilité, compétence et cohérence: pouvoir dire je ne sais pas, croire que les autres savent faire leur travail, et voir les engagements tenus dans le temps.",senior:"Dans une nouvelle équipe, il ne mesure pas la confiance à l'ambiance mais aux micro-risques: qui ose dire je ne sais pas, qui signale une erreur avant qu'elle soit visible, qui contredit une personne senior sans se justifier pendant dix minutes. Il modèle la vulnérabilité qu'il attend, puis observe si l'équipe l'imite. La confiance performée produit du silence poli; la confiance réelle produit des désaccords courts, directs et réparables.",errors:"<p><strong>Pattern 1 — La confiance supposée :</strong> l'équipe confond absence de conflit et sécurité psychologique parce que le silence ressemble à de la paix. Conséquence: les risques restent privés jusqu'au moment où ils deviennent coûteux.</p><p><strong>Pattern 2 — Le blâme public :</strong> sous pression, on corrige devant tous pour aller vite ou faire un exemple. Conséquence: chacun apprend à cacher ses erreurs plutôt qu'à les exposer tôt.</p><p><strong>Pattern 3 — La confiance sans garde-fous :</strong> on utilise la confiance comme excuse pour supprimer reviews, tests et documentation. Conséquence: la confiance devient fragile parce que chaque incident dépend de la mémoire et de la bonne volonté des personnes.</p>",invariants:"<p><strong>Ce qui change :</strong> les équipes, cultures et contextes. <strong>Ce qui ne change pas :</strong> sans confiance, chacun optimise sa protection individuelle plutôt que le résultat collectif.</p>",practice:{kind:"exercices",items:[{titre:"Évaluer la confiance dans son équipe",etapes:["Note si l'équipe dit facilement je ne sais pas, j'ai fait une erreur, j'ai besoin d'aide.","Identifie un moment récent où tu aurais pu modéliser cette vulnérabilité.","Choisis une action concrète pour renforcer la confiance cette semaine.","Identifie un comportement de ta part qui pourrait l'éroder."],output:"Diagnostic honnête + action de confiance + comportement à corriger.",critere:"Si tout semble parfait, vérifie la qualité réelle des désaccords: la confiance se voit quand il y a tension."}],piege:"Confondre bonne ambiance et confiance réelle. On peut rire ensemble et ne jamais oser dire une vérité difficile."},verification:["Différence entre confiance de vulnérabilité et de compétence ?","En rétro, un senior dit devant tout le monde qu'une junior a cassé la CI parce qu'elle n'a pas assez testé. Quel impact observes-tu sur elle, mais aussi sur les autres développeurs ?","Comment distinguer bonne ambiance et vraie confiance professionnelle ?"]}),codeReview:n({id:"codeReview",label:"Code review",icon:"👁",kind:"processus",niveau:"Fondation",why:"Le code review ne sert pas seulement à trouver des bugs. Il détecte des risques, transfère la connaissance et maintient l'alignement architectural.",system:"Il s'inscrit dans le workflow Git, dépend de la confiance et devient un canal de feedback quotidien sur le travail technique.",choice:"Une review constructive distingue blocker, suggestion et nit. Les Conventional Comments réduisent l'ambiguïté et empêchent de traiter une préférence comme un blocage.",senior:"Il lit d'abord l'intention de la PR, puis le diff. Il réserve les blockers aux bugs, failles et violations d'architecture, et marque explicitement les préférences comme suggestions. Il sait qu'une PR de 800 lignes ne reçoit pas une review: elle reçoit une bénédiction fatiguée. Il découpe donc le travail avant la review, pas après l'échec de la review.",errors:`<p><strong>Pattern 1 — Le style en review :</strong> le reviewer bloque sur ce qu'un formatter devrait régler parce que c'est facile à voir. Conséquence: la review devient une guerre de goûts et les vrais risques passent après.</p><p><strong>Pattern 2 — Review sans explication :</strong> sous contrainte de temps, on écrit "pas comme ça" sans raisonnement. Conséquence: l'auteur obéit ou se défend, mais n'apprend pas le modèle mental de l'équipe.</p><p><strong>Pattern 3 — LGTM automatique :</strong> on approuve par confiance ou pour ne pas bloquer. Conséquence: la PR perd son rôle de transfert de connaissance et les angles morts arrivent dans main.</p>`,invariants:"<p><strong>Ce qui change :</strong> GitHub, GitLab ou Gerrit. <strong>Ce qui ne change pas :</strong> une deuxième paire d'yeux voit ce que l'auteur ne voit plus.</p>",practice:{kind:"exercices",items:[{titre:"Améliorer ses commentaires de review",etapes:["Prends 3 commentaires récents ou imaginés.","Classe-les en blocker, suggestion ou nit.","Ajoute la raison, une alternative et le niveau de sévérité.","Réécris ceux qui seraient ambigus pour l'auteur."],output:"3 commentaires reclassifiés et réécrits.",critere:"Un bon commentaire doit être compris sans explication orale."}],piege:"Lire le diff avant l'intention de la PR. Une review commence par comprendre le problème visé."},verification:["Quels sont les 3 objectifs du code review ?","Dans une PR, tu vois un nom de variable moyen, une faille de sécurité et une architecture discutable mais réversible. Quels commentaires sont blockers, suggestions ou nits ?","Pourquoi LGTM sans lecture n'est pas une review ?"]}),feedbackDev:n({id:"feedbackDev",label:"Donner et recevoir du feedback",icon:"↔",kind:"humain",niveau:"Intermédiaire",why:"Le feedback est le mécanisme d'apprentissage le plus rapide d'une équipe. Sans lui, les problèmes s'accumulent jusqu'à devenir coûteux.",system:"Il dépend de la confiance, apparaît dans les reviews, les 1:1 et les rétrospectives, et prépare aussi les conversations hors équipe technique.",choice:"SBI structure le feedback en Situation, Behavior, Impact. Feedforward transforme l'observation passée en action future. Les 1:1 offrent le bon espace privé.",senior:"Il choisit le canal avant les mots: positif public quand il renforce un comportement utile, correctif privé quand il touche l'identité professionnelle. Il donne le feedback tant que l'événement est encore frais, mais pas pendant que la personne est défensive. Quand il reçoit un feedback dur, il ne plaide pas sa cause tout de suite: il reformule d'abord pour montrer qu'il a compris l'impact.",errors:`<p><strong>Pattern 1 — Feedback sandwich :</strong> on enrobe la critique pour se sentir bienveillant. Conséquence: le positif devient suspect et la personne retient seulement une critique floue.</p><p><strong>Pattern 2 — Accumulation :</strong> on évite l'inconfort jusqu'à l'entretien annuel. Conséquence: le feedback arrive trop tard, trop massif et trop difficile à transformer en action.</p><p><strong>Pattern 3 — Juger la personne :</strong> on dit "tu es désorganisé" parce que le raccourci est plus rapide que l'observation précise. Conséquence: la personne défend son identité au lieu de changer un comportement observable.</p>`,invariants:"<p><strong>Ce qui change :</strong> formats et rituels. <strong>Ce qui ne change pas :</strong> un feedback précis, proche et bienveillant aide plus qu'un jugement vague.</p>",practice:{kind:"exercices",items:[{titre:"Pratiquer SBI",etapes:["Choisis un comportement récent à commenter.","Écris la situation précise.","Décris le comportement observable.","Décris l'impact concret et vérifie qu'il n'y a pas de jugement de caractère."],output:"Feedback SBI prêt à être donné.",critere:"Chaque élément doit être vérifiable: situation, comportement, impact."}],piege:"Confondre feedback et conseil. Le feedback décrit l'impact passé; le conseil propose une action future."},verification:["Pourquoi SBI fonctionne mieux qu'un feedback vague ?","Un collègue livre une PR sans description et tu passes 25 minutes à reconstruire le contexte. Formule un feedback SBI complet.","Réécris tu es désorganisé en feedback SBI."]}),conflitsTechniques:n({id:"conflitsTechniques",label:"Gérer les conflits techniques",icon:"⚡",kind:"humain",niveau:"Intermédiaire",why:"Les conflits techniques sont normaux entre personnes compétentes. Le danger commence quand le désaccord sur une solution devient un jugement sur la personne.",system:"Ils apparaissent en review, planification et architecture. Ils nécessitent confiance, critères explicites et processus de décision clair.",choice:"RFC pour ouvrir un débat, ADR pour enregistrer la décision, disagree and commit pour avancer après débat honnête même sans unanimité.",senior:"Il sépare deux questions que les équipes mélangent: quelle option est meilleure, et qui porte la décision. Il rend les critères visibles avant que les ego ne s'attachent aux solutions: performance, maintenabilité, sécurité, vitesse, risque de rollback. Quand le débat tourne, il cherche le critère caché plutôt qu'un argument plus fort.",errors:"<p><strong>Pattern 1 — Argument d'autorité :</strong> une personne tranche par statut parce que le débat fatigue ou menace son territoire. Conséquence: la décision avance, mais le désaccord reste vivant sous forme de résistance passive.</p><p><strong>Pattern 2 — Bikeshedding :</strong> l'équipe débat fort de détails accessibles parce que les vrais sujets sont complexes et anxiogènes. Conséquence: l'énergie de décision est consommée là où l'impact est faible.</p><p><strong>Pattern 3 — Consensus forcé :</strong> on cherche l'unanimité pour éviter le conflit. Conséquence: l'équipe produit une décision tiède ou ne décide pas du tout.</p>",invariants:"<p><strong>Ce qui change :</strong> les formats de décision. <strong>Ce qui ne change pas :</strong> un conflit résolu par raisonnement produit mieux qu'un conflit résolu par volume ou statut.</p>",practice:{kind:"exercices",items:[{titre:"Structurer un désaccord technique",etapes:["Choisis un désaccord actuel ou récent.","Liste les options et leurs avantages objectifs.","Définis les critères de décision adaptés au contexte.","Évalue chaque option contre ces critères."],output:"Options, critères, évaluation et décision ou question de priorisation.",critere:"Un nouveau membre doit pouvoir comprendre le désaccord sans connaître les egos en présence."}],piege:"Chercher le consensus par peur du conflit. Le désaccord sain est une source de qualité."},verification:["Qu'est-ce que disagree and commit ?","Deux seniors s'opposent sur PostgreSQL vs MongoDB pour une feature critique. Comment sépares-tu critères techniques, ego et autorité de décision ?","Comment repérer un conflit d'ego déguisé ?"]}),onboarding:n({id:"onboarding",label:"Onboarding technique",icon:"🚀",kind:"processus",niveau:"Fondation",why:"Les premières semaines déterminent souvent les six mois suivants. Un bon onboarding rend autonome, confiant et contributif plus vite.",system:"L'onboarding construit les premières bases de confiance, teste la documentation et introduit les processus réels de l'équipe.",choice:"Buddy system, checklist d'onboarding et premier PR en semaine 1. Le nouveau membre doit contribuer tôt, petit, réel et accompagné.",senior:"Il regarde l'onboarding comme un test de réalité du système. Chaque question répétée est un bug de documentation ou de processus, pas une faiblesse du nouveau. Il planifie un premier PR petit, réel et accompagné parce que contribuer tôt transforme l'identité: la personne n'est plus invitée, elle fait partie du flux.",errors:`<p><strong>Pattern 1 — Immersion totale :</strong> l'équipe dit "tu apprendras en faisant" parce qu'elle n'a pas formalisé son savoir. Conséquence: le nouveau ne sait pas quelles questions poser et avance dans le brouillard.</p><p><strong>Pattern 2 — Pas de premier PR :</strong> on repousse la contribution pour éviter une erreur visible. Conséquence: la peur de toucher au code grandit avec chaque jour d'observation passive.</p><p><strong>Pattern 3 — Doc statique :</strong> la documentation n'a pas été rejouée depuis des mois. Conséquence: le nouveau doute de lui-même alors que c'est le système d'accueil qui ment.</p>`,invariants:"<p><strong>Ce qui change :</strong> outils et formats d'accueil. <strong>Ce qui ne change pas :</strong> un nouvel entrant sans guidage met plus de temps et commet plus d'erreurs évitables.</p>",practice:{kind:"exercices",items:[{titre:"Auditer l'onboarding",etapes:["Refais le setup en suivant uniquement la documentation.","Note chaque ambiguïté ou étape obsolète.","Liste les 3 questions posées par tous les nouveaux.","Mesure le temps jusqu'au premier PR."],output:"Lacunes de doc, questions récurrentes et temps jusqu'au premier PR.",critere:"Le setup doit être faisable sans aide orale."}],piege:"Mesurer seulement le ressenti de la première semaine; les lacunes apparaissent aussi en autonomie."},verification:["Pourquoi les questions d'onboarding sont-elles utiles ?","Une nouvelle développeuse bloque 3 heures sur le setup malgré le README. Elle s'excuse de poser trop de questions. Que dois-tu corriger: son comportement, la doc, ou le processus ?","Comment l'onboarding révèle-t-il les processus réels ?"]})},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"confianceEquipe",x:10,y:100,w:145,h:65},{id:"codeReview",x:205,y:100,w:120,h:65},{id:"feedbackDev",x:385,y:40,w:120,h:65},{id:"conflitsTechniques",x:385,y:165,w:165,h:65},{id:"onboarding",x:615,y:100,w:120,h:65}],edges:[{x1:155,y1:132,x2:203,y2:132,label:"construit"},{x1:325,y1:112,x2:383,y2:72,label:"renforce"},{x1:325,y1:150,x2:383,y2:188,label:"prévient"},{x1:505,y1:73,x2:613,y2:118,label:"facilite"},{x1:550,y1:200,x2:613,y2:152,label:"facilite"}]}}}),h=s({id:"collaboration-communication-externe",number:2,title:"Communiquer Hors de l'Équipe Technique",subtitle:"Traduire, cadrer les attentes, présenter et aligner sans perdre la nuance technique.",badge:"Fiche Co02 — Vision Systémique",meta:["5 nœuds · universel","8 sections / nœud"],readingTime:"35 min",description:"La communication qui transforme une expertise technique en décisions comprises hors de l'équipe.",accent:"communication",nodes:{translationTechnique:n({id:"translationTechnique",label:"Traduire le technique",icon:"↔",kind:"communication",niveau:"Fondation",why:"Un développeur qui ne parle qu'aux développeurs limite son impact. Traduire le technique, ce n'est pas simplifier bêtement: c'est choisir le bon niveau d'abstraction.",system:"Cette compétence alimente la gestion des attentes, les présentations, les mauvaises nouvelles et l'alignement stakeholder.",choice:"Pour un PM, parler impact feature et timeline. Pour un dirigeant, parler risque et ROI. Pour un designer, parler contraintes, alternatives et coût d'implémentation.",senior:"Avant d'expliquer, il identifie la décision que l'autre personne doit prendre. Un PM a besoin d'impact scope/délai, un dirigeant de risque/ROI, un designer de contraintes et alternatives. Il ne traduit pas tout: il choisit le niveau d'abstraction qui permet à l'interlocuteur d'agir sans croire comprendre plus qu'il ne comprend.",errors:"<p><strong>Pattern 1 — Dumbing down :</strong> on simplifie jusqu'à devenir faux pour éviter l'effort de pédagogie. Conséquence: l'interlocuteur prend une décision confiante sur une représentation incorrecte.</p><p><strong>Pattern 2 — Jargon non traduit :</strong> on garde p99, SLO ou latence parce que ce vocabulaire est naturel dans l'équipe. Conséquence: les non-techniciens acquiescent sans comprendre, puis sont surpris par les impacts.</p><p><strong>Pattern 3 — Solution avant problème :</strong> on annonce une migration ou refactor sans expliquer la douleur. Conséquence: le stakeholder voit un coût technique, pas une décision de risque.</p>",invariants:"<p><strong>Ce qui change :</strong> les sujets techniques. <strong>Ce qui ne change pas :</strong> celui qui communique porte la responsabilité d'adapter le message.</p>",practice:{kind:"exercices",items:[{titre:"Traduire un sujet pour 3 interlocuteurs",etapes:["Choisis une migration, dette ou décision technique.","Explique-la en 3 phrases pour un PM.","Explique-la en 3 phrases pour un dirigeant.","Explique-la avec une analogie pour une personne non-tech."],output:"3 traductions du même sujet.",critere:"La personne cible doit pouvoir reformuler correctement l'enjeu."}],piege:"Confondre acquiescement et compréhension. La vraie mesure est la décision qui suit."},verification:["Différence entre simplifier et rendre faux ?","Ton PM te demande pourquoi une refactorisation de deux semaines est nécessaire alors qu'aucune feature visible ne sortira. Comment traduis-tu le risque technique en impact produit ?","Donne une analogie simple pour expliquer le cache."]}),gererAttentes:n({id:"gererAttentes",label:"Gérer les attentes",icon:"⏱",kind:"communication",niveau:"Fondation",why:"La frustration naît souvent de l'écart entre attente et réalité. Gérer les attentes transforme les surprises en décisions anticipées.",system:"Cela dépend de bonnes estimations, de risques communiqués et d'un suivi régulier même quand tout va bien.",choice:"Under-promise avec prudence, communiquer les risques tôt, donner des mises à jour courtes et régulières pour réduire l'anxiété.",senior:"Il annonce l'incertitude avant qu'elle ne devienne une excuse. Il distingue estimation et engagement dans la même phrase: probabilité, hypothèses, signaux d'alerte et date de révision. Il sait qu'un retard annoncé tôt ressemble à du professionnalisme; le même retard annoncé à la deadline ressemble à une trahison.",errors:"<p><strong>Pattern 1 — Optimisme sans marge :</strong> on annonce le scénario idéal pour paraître efficace ou rassurer. Conséquence: la première surprise devient une rupture de confiance.</p><p><strong>Pattern 2 — Silence en retard :</strong> on attend la deadline par honte ou espoir que le problème se résolve. Conséquence: les autres perdent toute capacité d'ajuster leurs plans.</p><p><strong>Pattern 3 — Promettre pour faire plaisir :</strong> on évite un conflit maintenant en transformant une estimation en promesse. Conséquence: le conflit revient plus tard, avec moins d'options et plus d'émotion.</p>",invariants:"<p><strong>Ce qui change :</strong> outils et reporting. <strong>Ce qui ne change pas :</strong> la confiance vient d'engagements prévisibles et tenus.</p>",practice:{kind:"exercices",items:[{titre:"Communiquer les risques proactivement",etapes:["Choisis une tâche actuelle.","Liste les 3 risques principaux.","Formule pour chacun impact, signal d'alerte et prochaine action.","Identifie qui doit être prévenu."],output:"3 messages de risque prêts à envoyer.",critere:"Le message doit permettre à l'interlocuteur de décider ou ajuster ses plans."}],piege:"Sur-communiquer chaque micro-incertitude. Un risque communiqué doit avoir un impact réel."},verification:["Différence estimation/engagement ?","Mercredi, tu sais que la livraison promise vendredi a 60% de chances de glisser à mardi. Qu'écris-tu au PM aujourd'hui, et que gardes-tu pour plus tard ?","Limites de under-promise, over-deliver ?"]}),presentationTech:n({id:"presentationTech",label:"Présenter un sujet technique",icon:"📊",kind:"communication",niveau:"Intermédiaire",why:"Une bonne présentation technique conduit une audience d'une question à une décision. Elle multiplie l'impact d'une idée technique.",system:"Elle s'appuie sur la traduction technique et sert les décisions collectives, RFC, ADR et arbitrages.",choice:"SCQA pour les décisions, Pyramid principle pour les audiences pressées, demo-first pour ancrer dans le concret.",senior:"Il commence par la tension que l'audience reconnaît, puis révèle seulement les détails nécessaires à la décision. Il prépare la dernière slide avant la première: décision demandée, option recommandée, risque accepté. Si personne ne sait quoi faire après la présentation, ce n'était pas une présentation technique, c'était un transfert d'anxiété.",errors:`<p><strong>Pattern 1 — Bottom-up :</strong> on raconte tout le chemin parce qu'on veut prouver le sérieux du travail. Conséquence: l'audience décroche avant de comprendre la décision attendue.</p><p><strong>Pattern 2 — Sans call-to-action :</strong> on termine par "des questions ?" au lieu d'une demande claire. Conséquence: la décision reste implicite et revient dans un autre meeting.</p><p><strong>Pattern 3 — Slides denses :</strong> on met le document entier sur les slides par peur d'oublier. Conséquence: l'audience lit, n'écoute plus, et retient moins.</p>`,invariants:"<p><strong>Ce qui change :</strong> PowerPoint, Notion, vidéo ou demo. <strong>Ce qui ne change pas :</strong> une audience écoute mieux quand elle comprend vite ce qu'elle gagne.</p>",practice:{kind:"exercices",items:[{titre:"Structurer avec SCQA",etapes:["Choisis une décision technique à présenter.","Écris la Situation partagée.","Écris la Complication.","Formule la Question et la Réponse."],output:"Squelette SCQA en 6 à 10 phrases.",critere:"Sans les slides, on doit comprendre problème, question et réponse."}],piege:"Faire un hybride document/présentation. Un slide accompagne la parole; un document doit vivre seul."},verification:["Pourquoi SCQA bat souvent le chronologique ?","Tu présentes à 8 personnes une migration d'authentification qui demande une décision budget/risque. Quelle est ta première slide et quelle décision demandes-tu à la fin ?","Différence entre slide et document ?"]}),direBonneNouvelle:n({id:"direBonneNouvelle",label:"Annoncer bonnes et mauvaises nouvelles",icon:"📢",kind:"communication",niveau:"Intermédiaire",why:"Un projet a toujours des hauts et des bas. Savoir communiquer clairement les deux construit une crédibilité durable.",system:"Cette compétence complète la gestion des attentes et nourrit l'alignement stakeholder, surtout en contexte de tension.",choice:"Mauvaise nouvelle: directe, tôt, contextualisée, avec proposition. Bonne nouvelle: exacte, prouvée par des données, sans exagération.",senior:"Il prépare toujours la question implicite: qu'est-ce qu'on fait maintenant ? Il donne la mauvaise nouvelle assez tôt pour préserver des options, et assez directement pour éviter que l'autre doive la deviner. Il ne compense pas une mauvaise nouvelle par du flou positif: il compense par un plan.",errors:"<p><strong>Pattern 1 — Mauvaise nouvelle enterrée :</strong> on la cache à la fin d'un email positif pour éviter l'inconfort. Conséquence: l'interlocuteur se sent manipulé et relit tout le message avec méfiance.</p><p><strong>Pattern 2 — Sans proposition :</strong> on annonce le problème sans prochaine étape parce qu'on n'a pas encore tout résolu. Conséquence: l'anxiété augmente et le stakeholder remplit les blancs avec le pire scénario.</p><p><strong>Pattern 3 — Bonne nouvelle exagérée :</strong> on amplifie un succès pour regagner du crédit. Conséquence: la crédibilité future baisse quand la réalité rattrape le récit.</p>",invariants:"<p><strong>Ce qui change :</strong> canal et format. <strong>Ce qui ne change pas :</strong> une mauvaise nouvelle tôt et claire cause moins de dégâts qu'une surprise tardive.</p>",practice:{kind:"exercices",items:[{titre:"Formuler une mauvaise nouvelle",etapes:["Choisis un retard, bug ou scope réduit.","Écris le fait directement.","Ajoute le contexte sans excuse.","Ajoute une proposition d'action concrète."],output:"Message prêt à envoyer: fait, contexte, proposition.",critere:"Le message doit être compréhensible sans réunion d'explication."}],piege:"Attendre d'avoir la solution complète avant d'annoncer le problème."},verification:["Structure d'une mauvaise nouvelle efficace ?","Un bug critique force à retirer une feature annoncée en démo client demain. Rédige l'ordre des informations dans ton message au stakeholder.","Différence entre responsabilité et excuse ?"]}),alignementStakeholders:n({id:"alignementStakeholders",label:"Aligner les stakeholders",icon:"🎯",kind:"communication",niveau:"Avancé",why:"Un projet peut échouer malgré un bon code si les parties prenantes ne partagent pas le problème, les contraintes et la direction.",system:"L'alignement synthétise traduction, attentes, présentation, processus de décision et compréhension des parties prenantes.",choice:"Pré-alignement avant réunion, communication en cercles concentriques, et RACI pour clarifier qui fait, décide, consulte et informe.",senior:"Il sait que les grandes décisions se prennent rarement pendant la réunion finale. Avant, il cartographie intérêts, peurs et veto possibles, puis parle aux personnes clés une par une. La réunion sert à rendre visible un alignement déjà travaillé, pas à découvrir en public la première objection majeure.",errors:"<p><strong>Pattern 1 — Stakeholder oublié :</strong> on consulte les personnes visibles et on oublie une équipe affectée. Conséquence: une décision techniquement juste échoue à l'exécution.</p><p><strong>Pattern 2 — Alignement par email :</strong> on demande une validation froide sur un sujet politique pour gagner du temps. Conséquence: les objections sortent tard, sans nuance, et durcissent les positions.</p><p><strong>Pattern 3 — Aligner sans écouter :</strong> on confond alignement et persuasion parce qu'on veut défendre sa solution. Conséquence: les gens se sentent utilisés plutôt qu'impliqués et résistent après la décision.</p>",invariants:"<p><strong>Ce qui change :</strong> taille et politique de l'organisation. <strong>Ce qui ne change pas :</strong> une décision co-construite s'exécute mieux qu'une décision imposée.</p>",practice:{kind:"exercices",items:[{titre:"Cartographier les stakeholders",etapes:["Choisis une décision technique importante.","Liste toutes les personnes ou équipes affectées.","Identifie leurs intérêts et objections possibles.","Planifie l'ordre et le format de consultation."],output:"Carte stakeholder + objections + plan de pré-alignement.",critere:"Aucune objection majeure ne doit apparaître pour la première fois en réunion finale."}],piege:"Confondre consultation et vote. Tout le monde peut être entendu sans avoir un veto."},verification:["Pourquoi les décisions importantes se préparent avant la réunion ?","Tu dois arrêter une intégration utilisée par Sales mais coûteuse pour l'équipe technique. Qui consultes-tu avant la réunion finale, et que cherches-tu à apprendre ?","Pourquoi les cercles concentriques réduisent les malentendus ?"]})},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"translationTechnique",x:10,y:100,w:175,h:65},{id:"gererAttentes",x:235,y:100,w:140,h:65},{id:"presentationTech",x:430,y:40,w:155,h:65},{id:"direBonneNouvelle",x:430,y:165,w:165,h:65},{id:"alignementStakeholders",x:655,y:100,w:155,h:65}],edges:[{x1:185,y1:132,x2:233,y2:132,label:"facilite"},{x1:375,y1:112,x2:428,y2:72,label:"structure"},{x1:375,y1:150,x2:428,y2:188,label:"clarifie"},{x1:585,y1:73,x2:653,y2:118,label:"construit"},{x1:595,y1:200,x2:653,y2:152,label:"construit"}]}}}),x=s({id:"collaboration-documentation",number:3,title:"Documentation Vivante",subtitle:"Capturer le pourquoi, maintenir la mémoire collective et éviter que la doc devienne une dette.",badge:"Fiche Co03 — Vision Systémique",meta:["5 nœuds · universel","8 sections / nœud"],readingTime:"35 min",description:"Documentation utile, maintenue, proche du code et portée par une culture d'équipe.",accent:"communication",nodes:{pourquoiDocumenter:n({id:"pourquoiDocumenter",label:"Pourquoi documenter",icon:"📝",kind:"communication",niveau:"Fondation",why:"La documentation n'est pas une archive morte. Elle aide le développeur de demain, souvent soi-même dans six mois, à retrouver le raisonnement perdu.",system:"Elle rend l'onboarding possible, préserve les décisions, soutient les runbooks et sert de mémoire organisationnelle quand les personnes changent.",choice:"Documenter pour soi futur, pour l'équipe et pour l'extérieur. Chaque audience demande un niveau de contexte différent.",senior:"Il ne demande pas seulement ce qui manque dans la doc; il demande quelle décision serait impossible si la personne clé partait demain. Il applique le test du bus aux raisonnements, pas aux fichiers: pourquoi cette architecture, pourquoi ce contournement, pourquoi cette dette acceptée. Il documente ce qui est non évident, contre-intuitif ou justifié par un contexte invisible.",errors:"<p><strong>Pattern 1 — Documentation exhaustive :</strong> l'équipe documente tout pour se rassurer. Conséquence: le bruit masque les informations rares et personne ne sait quoi lire.</p><p><strong>Pattern 2 — Le code se documente lui-même :</strong> on confond lisibilité de l'implémentation et mémoire du raisonnement. Conséquence: le quoi reste visible, mais le pourquoi disparaît.</p><p><strong>Pattern 3 — Doc après coup :</strong> on attend la fin pour documenter parce que livrer paraît plus urgent. Conséquence: les alternatives rejetées, contraintes et arbitrages sont déjà oubliés.</p>",invariants:"<p><strong>Ce qui change :</strong> outils et formats. <strong>Ce qui ne change pas :</strong> la connaissance non capturée se perd avec le temps et les départs.</p>",practice:{kind:"exercices",items:[{titre:"Identifier les priorités de documentation",etapes:["Applique le test du bus au projet.","Liste 3 connaissances critiques non documentées.","Estime leur coût de reconstruction.","Priorise par coût de reconstruction divisé par temps de documentation."],output:"Top 3 des connaissances à documenter.",critere:"La documentation prioritaire est celle qui serait coûteuse à reconstruire."}],piege:"Documenter ce qui est confortable plutôt que ce qui est difficile à retrouver."},verification:["Qu'est-ce que le test du bus ?","Le seul développeur qui connaît le système de paiement part dans deux semaines. Quelles trois connaissances documentes-tu avant les détails d'implémentation ?","Différence entre doc pour soi, équipe et extérieur ?"]}),docCommeDette:n({id:"docCommeDette",label:"La doc comme dette",icon:"📊",kind:"processus",niveau:"Fondation",why:"Une documentation obsolète est pire qu'une absence de documentation: elle donne confiance à une information fausse.",system:"La dette documentaire suit la dette technique. Elle doit être traitée dans les reviews, la Definition of Done et les processus d'équipe.",choice:"Inclure la doc dans la Definition of Done, la co-localiser avec le code, et tester les exemples quand c'est possible.",senior:"Il rend la fraîcheur visible: propriétaire, dernière révision, zone de validité. Une doc sans signal de fraîcheur devient suspecte même quand elle est vraie. Il préfère supprimer une page trompeuse plutôt que laisser une équipe perdre deux heures à suivre une procédure morte.",errors:"<p><strong>Pattern 1 — Wiki fantôme :</strong> les pages s'accumulent sans propriétaire parce que créer une page est plus gratifiant que la maintenir. Conséquence: personne ne sait si l'information est vraie.</p><p><strong>Pattern 2 — Documenter après merge :</strong> on sort la doc du flux de livraison pour aller plus vite. Conséquence: le PR de documentation n'arrive jamais ou arrive sans le contexte vivant.</p><p><strong>Pattern 3 — Trop de doc :</strong> on documente des évidences par peur d'oublier. Conséquence: le coût de maintenance dépasse la valeur et toute la doc perd en crédibilité.</p>",invariants:"<p><strong>Ce qui change :</strong> doc-as-code, wiki ou Notion. <strong>Ce qui ne change pas :</strong> toute information non maintenue dérive vers l'obsolescence.</p>",practice:{kind:"exercices",items:[{titre:"Auditer la santé documentaire",etapes:["Choisis 5 pages de doc.","Vérifie date, exactitude et exemples.","Identifie les pages obsolètes ou ambiguës.","Planifie les 3 corrections les plus critiques."],output:"Audit de 5 pages + plan de correction.",critere:"Plus de 2 pages obsolètes sur 5 signalent un problème de processus."}],piege:"Corriger les pages sans changer le processus qui les a laissées pourrir."},verification:["Pourquoi une doc obsolète est-elle dangereuse ?","Tu suis une page d'onboarding vieille de 18 mois et trois commandes ne fonctionnent plus. Que fais-tu de la page, du processus de review et de la Definition of Done ?","Pourquoi co-localiser doc et code ?"]}),quoiDocumenter:n({id:"quoiDocumenter",label:"Quoi documenter",icon:"❓",kind:"communication",niveau:"Fondation",why:"Les équipes documentent souvent le quoi visible dans le code, et oublient le pourquoi: alternatives rejetées, contraintes et contexte.",system:"Ce nœud guide ADRs, runbooks, post-mortems, commentaires utiles et documentation d'API.",choice:"Priorité aux décisions et raisonnements, puis processus non évidents, contexte/contraintes, et enfin interfaces/API.",senior:"Il documente les décisions plus que les implémentations, surtout les décisions négatives. Quand l'équipe a déjà rejeté une option séduisante, il capture pourquoi; sinon le prochain nouveau la reproposera avec la même énergie. Un commentaire utile explique pourquoi une solution étrange existe, pas ce que chaque ligne fait.",errors:"<p><strong>Pattern 1 — Commenter le lisible :</strong> on paraphrase le code parce que c'est facile à produire. Conséquence: les commentaires ajoutent du volume sans réduire l'incertitude.</p><p><strong>Pattern 2 — Oublier les décisions négatives :</strong> on documente seulement ce qui a été choisi. Conséquence: les débats rejetés reviennent à chaque arrivée ou changement de contexte.</p><p><strong>Pattern 3 — FIXME sans contexte :</strong> on signale une dette sans impact, propriétaire ni condition de remboursement. Conséquence: la dette devient impossible à prioriser.</p>",invariants:"<p><strong>Ce qui change :</strong> formats. <strong>Ce qui ne change pas :</strong> les informations rares et coûteuses à reconstruire valent plus que les informations visibles.</p>",practice:{kind:"exercices",items:[{titre:"Écrire un ADR",etapes:["Choisis une décision technique récente.","Écris le contexte.","Liste les options considérées et rejetées.","Note la décision et ses conséquences."],output:"ADR complet dans docs/decisions.",critere:"Quelqu'un qui arrive dans 2 ans doit comprendre pourquoi le système est ainsi."}],piege:"Réserver les ADRs aux très grandes décisions. Les petites conventions répétées méritent aussi mémoire."},verification:["Pourquoi documenter le pourquoi ?","L'équipe a choisi REST au lieu de GraphQL après débat. Six mois plus tard, un nouveau propose GraphQL. Que doit contenir l'ADR pour éviter de rejouer le débat ?","Pourquoi documenter les options rejetées ?"]}),documentationCode:n({id:"documentationCode",label:"Documentation dans le code",icon:"💬",kind:"processus",niveau:"Fondation",why:"La documentation proche du code est la plus consultée naturellement et la plus susceptible d'être maintenue.",system:"Elle vit dans commentaires, commits, descriptions de PR, docstrings et conventions de review.",choice:"Commentaires pour le pourquoi, commits pour le changement, PR pour la décision, docstrings pour l'interface publique.",senior:"Il traite commit, description de PR et commentaire inline comme trois couches de mémoire. Le commit explique le changement durable, la PR explique le contexte de décision, le commentaire explique le pourquoi local que le code ne peut pas porter. Il supprime les commentaires qui mentent avec autant d'énergie qu'il corrige un test rouge.",errors:"<p><strong>Pattern 1 — Commentaires menteurs :</strong> le code change mais le commentaire reste parce que personne ne le teste. Conséquence: le lecteur fait confiance à l'information la plus fausse.</p><p><strong>Pattern 2 — PR sans description :</strong> l'auteur pense que le diff suffit parce que le contexte est frais dans sa tête. Conséquence: le reviewer devine l'intention et l'historique devient inutile.</p><p><strong>Pattern 3 — TODO sans tracking :</strong> on écrit une promesse dans le code pour soulager sa conscience. Conséquence: la dette n'a ni propriétaire, ni priorité, ni condition de sortie.</p>",invariants:"<p><strong>Ce qui change :</strong> langages et conventions. <strong>Ce qui ne change pas :</strong> la documentation co-localisée est mieux maintenue que la documentation lointaine.</p>",practice:{kind:"exercices",items:[{titre:"Améliorer un fichier réel",etapes:["Choisis un fichier récemment modifié.","Identifie 3 endroits non évidents.","Ajoute un commentaire qui répond à pourquoi c'est ainsi.","Vérifie que le commentaire ne paraphrase pas le code."],output:"3 commentaires utiles centrés sur le pourquoi.",critere:"Si un meilleur nommage remplace le commentaire, corrige le code plutôt que d'ajouter du texte."}],piege:"Utiliser les commentaires pour compenser un code illisible."},verification:["Règle d'or d'un commentaire inline ?","Tu tombes sur un commentaire qui contredit le comportement actuel du code. Que vérifies-tu avant de le supprimer ou le réécrire ?","Pourquoi un commentaire qui ment est pire que rien ?"]}),culturedoc:n({id:"culturedoc",label:"Culture de documentation",icon:"🌱",kind:"organisation",niveau:"Avancé",why:"La documentation est d'abord une culture. Les outils réduisent la friction, mais ne créent pas la motivation.",system:"La culture documentaire dépend de la confiance, du leadership, de la Definition of Done et du temps réellement alloué.",choice:"Traiter la doc comme first-class citizen, voir les leaders documenter, valoriser publiquement les contributions à la documentation.",senior:"Il regarde les signaux réels, pas les slogans: est-ce que les estimations incluent la doc, est-ce que les reviews bloquent une décision non documentée, est-ce qu'une contribution doc est célébrée comme une contribution produit ? La culture change quand le comportement attendu coûte ou rapporte quelque chose dans le système.",errors:"<p><strong>Pattern 1 — Attendre la stabilité :</strong> on reporte la doc parce que le code bouge encore. Conséquence: le code ne devient jamais assez stable et la mémoire disparaît pendant l'évolution.</p><p><strong>Pattern 2 — Changer d'outil :</strong> on migre vers Notion ou Confluence pour éviter de traiter les comportements. Conséquence: le nouveau wiki devient l'ancien wiki avec une meilleure interface.</p><p><strong>Pattern 3 — Forcer la doc :</strong> on impose une case à cocher sans valeur claire. Conséquence: l'équipe produit du remplissage qui satisfait le processus et n'aide personne.</p>",invariants:"<p><strong>Ce qui change :</strong> outils et templates. <strong>Ce qui ne change pas :</strong> une culture change par comportements répétés, pas par décret.</p>",practice:{kind:"exercices",items:[{titre:"Évaluer la culture doc",etapes:["Vérifie si la doc est estimée, reviewée et dans la Definition of Done.","Liste les deux dernières contributions doc valorisées publiquement.","Identifie un signal implicite que tu envoies contre la doc.","Définis une action observable sur deux semaines."],output:"Diagnostic culturel + action observable.",critere:"Une action doit être spécifique: par exemple ajouter une question doc à chaque review cette semaine."}],piege:"Traiter un problème culturel comme un problème d'outil."},verification:["Pourquoi la doc est-elle culturelle ?","Ton équipe dit valoriser la documentation, mais les PRs sans doc passent toujours et personne ne remercie les corrections de doc. Quels signaux corriges-tu en premier ?","Pourquoi punir l'absence de doc produit du remplissage ?"]})},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"pourquoiDocumenter",x:10,y:100,w:165,h:65},{id:"docCommeDette",x:225,y:100,w:155,h:65},{id:"quoiDocumenter",x:435,y:40,w:140,h:65},{id:"documentationCode",x:435,y:165,w:160,h:65},{id:"culturedoc",x:660,y:100,w:150,h:65}],edges:[{x1:175,y1:132,x2:223,y2:132,label:"alimente"},{x1:380,y1:112,x2:433,y2:72,label:"clarifie"},{x1:380,y1:150,x2:433,y2:188,label:"structure"},{x1:575,y1:73,x2:658,y2:118,label:"construit"},{x1:595,y1:200,x2:658,y2:152,label:"construit"}]}}}),C=s({id:"collaboration-organisation",number:4,title:"Organiser le Travail",subtitle:"Estimer, choisir le bon mode de communication, ritualiser et décider sans bloquer l'équipe.",badge:"Fiche Co04 — Vision Systémique",meta:["5 nœuds · universel","8 sections / nœud"],readingTime:"35 min",description:"Les mécanismes d'organisation qui protègent le travail profond et rendent les décisions explicites.",accent:"organisation",nodes:{estimation:n({id:"estimation",label:"Estimation",icon:"⏱",kind:"organisation",niveau:"Fondation",why:"Sans estimation fiable, les attentes sont mal calibrées et chaque retard devient une surprise. L'estimation est une prévision probabiliste, pas une promesse.",system:"Elle alimente attentes, priorisation, roadmap technique et planification de sprint.",choice:"Story points pour la complexité relative, t-shirt sizing pour le tri rapide, décomposition pour la précision, three-point estimation pour l'incertitude.",senior:"Il donne des fourchettes et nomme l'incertitude: probablement 3 jours, entre 1 et 5 selon le legacy. Il regarde aussi l'historique de l'équipe: certains sous-estiment toujours l'intégration, d'autres oublient les reviews. L'estimation devient meilleure quand elle calibre les biais récurrents, pas quand elle prétend être précise.",errors:"<p><strong>Pattern 1 — Optimisme par défaut :</strong> l'équipe estime le chemin heureux parce qu'elle imagine l'exécution sans interruptions ni surprises. Conséquence: chaque imprévu ressemble à un échec au lieu d'être intégré à la prévision.</p><p><strong>Pattern 2 — Sans décomposition :</strong> on donne un chiffre global pour éviter l'effort d'analyse. Conséquence: les sous-problèmes cachés apparaissent trop tard pour ajuster le plan.</p><p><strong>Pattern 3 — Confondre estimation et engagement :</strong> une prévision devient promesse parce que personne n'a explicité l'incertitude. Conséquence: la confiance baisse même quand l'estimation initiale était honnête.</p>",invariants:"<p><strong>Ce qui change :</strong> méthodes et outils. <strong>Ce qui ne change pas :</strong> une fourchette honnête vaut mieux qu'une précision fausse.</p>",practice:{kind:"exercices",items:[{titre:"Estimer par décomposition",etapes:["Choisis une feature moyenne.","Décompose-la en tâches de 1 à 2 jours.","Estime optimiste, probable et pessimiste pour chaque tâche.","Compare le total à ton intuition initiale."],output:"Feature décomposée + estimation three-point.",critere:"L'incertitude doit varier selon les sous-problèmes; sinon l'analyse est trop plate."}],piege:"Confondre décomposer pour estimer et décomposer pour planifier."},verification:["Différence estimation/engagement ?","Ton équipe annonce 3 jours pour une feature legacy sans décomposition. Au deuxième jour, elle découvre une dépendance non documentée. Comment aurais-tu formulé l'estimation initiale ?","Que résout le three-point estimation ?"]}),asyncVsSync:n({id:"asyncVsSync",label:"Async vs synchrone",icon:"⚡",kind:"organisation",niveau:"Fondation",why:"Le choix async/sync détermine combien de temps ininterrompu reste pour le travail profond. Une réunion coûte aussi la reconcentration après interruption.",system:"Il structure les rituels, les décisions et la relation aux stakeholders qui attendent parfois une disponibilité immédiate.",choice:"Async par défaut, synchrone pour urgence, émotion et ambiguïté forte. Protéger des plages de focus et regrouper les échanges synchrones.",senior:"Il protège le temps profond comme une ressource d'équipe, pas comme une préférence personnelle. Il normalise la réponse différée: je suis en focus, je réponds dans 2h. Mais il ne pousse pas tout en async: dès que le sujet porte une charge émotionnelle ou une ambiguïté relationnelle, il passe en synchrone avant que le texte n'invente un ton.",errors:"<p><strong>Pattern 1 — Réunion réflexe :</strong> on transforme chaque incertitude en call parce que parler semble plus rapide. Conséquence: le coût collectif explose et le travail profond disparaît.</p><p><strong>Pattern 2 — Réponse immédiate attendue :</strong> chacun surveille Slack pour éviter de paraître indisponible. Conséquence: l'attention se fragmente et les tâches complexes avancent moins.</p><p><strong>Pattern 3 — Async pour l'émotionnel :</strong> on traite un feedback difficile par écrit pour éviter l'inconfort. Conséquence: le message est lu dans sa version la plus dure et le conflit grossit.</p>",invariants:"<p><strong>Ce qui change :</strong> Slack, Notion ou GitHub Discussions. <strong>Ce qui ne change pas :</strong> le travail complexe a besoin d'attention longue et non fragmentée.</p>",practice:{kind:"exercices",items:[{titre:"Auditer async/sync",etapes:["Compte les réunions de ta semaine type.","Pour chaque réunion, teste si l'objectif peut être async.","Compte tes blocs de 2h sans interruption.","Identifie 2 réunions à supprimer ou convertir."],output:"Inventaire des réunions + blocs de focus + conversions candidates.",critere:"Moins de 3 blocs de 2h par semaine signale un calendrier hostile au travail profond."}],piege:"Confondre disponibilité et productivité."},verification:["Quel est le vrai coût d'une interruption ?","Deux développeurs s'envoient des messages secs sur Slack à propos d'une review bloquée depuis 24h. Est-ce encore un sujet async, et que fais-tu ?","Différence entre disponible et productif ?"]}),rituelsEquipe:n({id:"rituelsEquipe",label:"Rituels d'équipe",icon:"🔄",kind:"processus",niveau:"Fondation",why:"Les rituels sont des points de synchronisation intentionnels. Ils détectent les blocages, donnent un rythme et créent un espace d'amélioration.",system:"Ils structurent le synchrone, alimentent les décisions et portent la rétro comme mécanisme d'amélioration continue.",choice:"Standup pour les blocages, planning pour choisir le travail, rétro pour améliorer le système, demo pour obtenir du feedback stakeholder.",senior:"Il protège chaque rituel de sa dérive naturelle. Le standup veut devenir reporting, la rétro veut devenir catharsis, le planning veut devenir design meeting. Il ramène chaque rituel à sa question centrale: quel blocage, quelle décision, quelle amélioration, quel feedback ? Si la question n'est plus servie, le rituel change.",errors:"<p><strong>Pattern 1 — Standup reporting :</strong> chacun raconte hier parce que cela ressemble à de la transparence. Conséquence: les blocages arrivent trop tard et l'équipe confond activité avec coordination.</p><p><strong>Pattern 2 — Rétro sans actions :</strong> l'équipe verbalise les douleurs sans propriétaire ni délai. Conséquence: les mêmes plaintes reviennent et la rétro perd sa crédibilité.</p><p><strong>Pattern 3 — Rituels sacrés :</strong> on garde Scrum tel quel parce que le processus rassure. Conséquence: l'équipe sert la méthode au lieu d'utiliser la méthode.</p>",invariants:"<p><strong>Ce qui change :</strong> remote, hybride ou co-localisé. <strong>Ce qui ne change pas :</strong> sans rythmes clairs, les équipes dérivent et les blocages s'accumulent.</p>",practice:{kind:"exercices",items:[{titre:"Évaluer les rituels",etapes:["Liste les rituels d'équipe et leur durée réelle.","Associe à chacun son objectif principal.","Vérifie si la dernière occurrence a atteint l'objectif.","Propose une modification concrète au rituel le plus problématique."],output:"Audit rituels + modification proposée.",critere:"La modification doit mieux servir l'objectif, pas seulement rendre la réunion moins ennuyeuse."}],piege:"Changer les rituels chaque semaine. Il faut assez de stabilité pour mesurer l'effet."},verification:["Vrai objectif du standup ?","Depuis trois sprints, la rétro produit toujours la plainte 'trop d'interruptions', mais aucune action ne change le calendrier. Que manque-t-il au rituel ?","Pourquoi adapter les rituels à l'équipe ?"]}),prioritisation:n({id:"prioritisation",label:"Priorisation de l'équipe",icon:"⬡",kind:"organisation",niveau:"Intermédiaire",why:"Quand il y a plus de travail que de temps, la priorisation choisit explicitement ce qui sera fait et ce qui ne le sera pas.",system:"Elle s'appuie sur estimation, métriques produit, impact/effort et planification de sprint.",choice:"MoSCoW pour clarifier le scope, RICE pour comparer, WSJF pour optimiser valeur/temps et risque.",senior:"Il garde une liste Won't do aussi importante que la liste Will do. Il sait que la priorisation est politique: choisir A, c'est décevoir quelqu'un qui voulait B. Il rend donc les critères visibles — impact, risque, effort, timing — pour que le désaccord porte sur les critères plutôt que sur l'influence des personnes.",errors:"<p><strong>Pattern 1 — Urgence perçue :</strong> l'équipe fait ce qui crie le plus fort parce que le bruit ressemble à de l'importance. Conséquence: le travail visible remplace le travail à fort impact.</p><p><strong>Pattern 2 — Backlog infini :</strong> on conserve 300 items pour ne pas dire non. Conséquence: le backlog cesse d'être un outil de décision et devient un cimetière d'idées.</p><p><strong>Pattern 3 — Consensus forcé :</strong> on dilue les priorités pour satisfaire tout le monde. Conséquence: personne n'est vraiment servi et aucun arbitrage n'est assumé.</p>",invariants:"<p><strong>Ce qui change :</strong> frameworks. <strong>Ce qui ne change pas :</strong> sans priorisation explicite, le visible bat l'important.</p>",practice:{kind:"exercices",items:[{titre:"Prioriser avec MoSCoW",etapes:["Prends 10 items de backlog.","Classe-les Must, Should, Could, Won't.","Vérifie que les Must restent sous 60%.","Documente les raisons des Won't."],output:"10 items classés et raisons des Won't.",critere:"Chaque Must doit être défendable en valeur ou risque concret."}],piege:"Prioriser seulement les features en oubliant dette, infra, doc et processus."},verification:["Pourquoi l'urgence perçue est trompeuse ?","Ton backlog contient 10 items et 8 sont classés Must par des stakeholders différents. Comment fais-tu apparaître le vrai arbitrage ?","Pourquoi un décideur clair est nécessaire ?"]}),decisionProcess:n({id:"decisionProcess",label:"Processus de décision",icon:"⚖",kind:"processus",niveau:"Intermédiaire",why:"Sans processus explicite, les décisions se prennent par autorité informelle, rhétorique ou évitement.",system:"Le processus de décision complète la gestion des conflits, l'alignement stakeholder et les rituels où les arbitrages se produisent.",choice:"Consentement plutôt que consensus, DACI pour clarifier les rôles, essai limité pour trancher par données, RFC pour les décisions importantes.",senior:"Il calibre le processus au coût de l'erreur. Une décision réversible se prend vite avec peu de cérémonie; une décision difficile à inverser mérite consultation, critères et trace écrite. Il nomme l'Approver avant la discussion, parce qu'une réunion sans décideur fabrique seulement des opinions alignées temporairement.",errors:"<p><strong>Pattern 1 — Absence de décision :</strong> la réunion termine sans phrase de décision parce que personne ne possède la conclusion. Conséquence: le sujet revient, plus chargé, au prochain meeting.</p><p><strong>Pattern 2 — Plus convaincant gagne :</strong> l'équipe confond aisance orale et qualité de jugement. Conséquence: les personnes plus calmes cessent d'apporter des objections utiles.</p><p><strong>Pattern 3 — Redébattre sans ADR :</strong> les décisions passées ne sont pas tracées parce qu'elles semblaient évidentes. Conséquence: chaque arrivée rouvre les mêmes débats et ralentit l'équipe.</p>",invariants:"<p><strong>Ce qui change :</strong> vote, DACI, RFC ou consentement. <strong>Ce qui ne change pas :</strong> sans processus, le pouvoir informel décide.</p>",practice:{kind:"exercices",items:[{titre:"Implémenter DACI",etapes:["Choisis une décision importante.","Nomme Driver, Approver, Contributors et Informed.","Vérifie qu'il y a un seul Approver.","Fixe une date limite et ce qui arrive si elle n'est pas tenue."],output:"DACI complet avec personnes nommées et deadline.",critere:"Si l'Approver est un groupe, la décision reste ambiguë."}],piege:"Appliquer le même processus à un nom de variable et à une migration de base."},verification:["Différence consensus/consentement ?","Une réunion de 7 personnes débat 45 minutes d'une migration, puis se termine par 'on verra'. Quel rôle DACI manquait et comment le fixes-tu avant la prochaine discussion ?","Comment calibrer RFC vs décision rapide ?"]})},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"estimation",x:10,y:100,w:130,h:65},{id:"asyncVsSync",x:190,y:100,w:145,h:65},{id:"rituelsEquipe",x:390,y:40,w:130,h:65},{id:"prioritisation",x:390,y:165,w:135,h:65},{id:"decisionProcess",x:590,y:100,w:160,h:65}],edges:[{x1:140,y1:132,x2:188,y2:132,label:"structure"},{x1:335,y1:112,x2:388,y2:72,label:"alimente"},{x1:335,y1:150,x2:388,y2:188,label:"clarifie"},{x1:520,y1:73,x2:588,y2:118,label:"clarifie"},{x1:525,y1:198,x2:588,y2:152,label:"clarifie"}]}}}),k=[b,h,x,C];export{l as a,y as b,k as c,P as d,v as u};
